    internal InnerMediaCapturePipelineAudioArtifactsConfigurationFactory AudioFactory { get; set; }

    internal InnerMediaCapturePipelineCompositedVideoArtifactsConfigurationFactory CompositedVideoFactory { get; set; }

    protected override Humidifier.Chime.MediaCapturePipelineTypes.ArtifactsConfiguration Create()
    {
        var artifactsConfigurationResult = CreateArtifactsConfiguration();
        factoryAction?.Invoke(artifactsConfigurationResult);

        return artifactsConfigurationResult;
    }

    private Humidifier.Chime.MediaCapturePipelineTypes.ArtifactsConfiguration CreateArtifactsConfiguration()
    {
        var artifactsConfigurationResult = new Humidifier.Chime.MediaCapturePipelineTypes.ArtifactsConfiguration();

        return artifactsConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Chime.MediaCapturePipelineTypes.ArtifactsConfiguration result)
    {
        base.CreateChildren(result);

        result.Video ??= VideoFactory?.Build();
        result.Content ??= ContentFactory?.Build();
        result.Audio ??= AudioFactory?.Build();
        result.CompositedVideo ??= CompositedVideoFactory?.Build();
    }

} // End Of Class

